window.docContents[166].resolve({"/Quadratic-Mean-Differentiability/#Statlib--Quadratic-Mean-Differentiability--The-mean-zero-score-theorem--The-formalized-statement-and-proof":{"contents":"The mean-zero score result is the theorem integral_score_eq_zero, stated and proved\nin Lean below. The proof realizes the difference-of-squares argument above: the limits\nT_1/t \\to 0 and T_2/t \\to \\mathbb{E}_{\\mathbb{P}_{\\theta^\\star}}(A(h)) are the\nlemmas tendsto_zero and tendsto_integral_score, and uniqueness of limits pins the\nscore integral to 0.\n\n\n\n","context":"Statlib\u0009Quadratic Mean Differentiability\u0009The mean-zero score theorem","header":"3.4.2. The formalized statement and proof","id":"/Quadratic-Mean-Differentiability/#Statlib--Quadratic-Mean-Differentiability--The-mean-zero-score-theorem--The-formalized-statement-and-proof"}});